class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long countUpTo(java.math.BigInteger x, int b) {
    String s = x.toString(b);
    int n = s.length();
    long[][] ways = new long[n + 1][b + 1];
    for (int d = 0; d < b; d++) ways[0][d] = 1;
    for (int len = 1; len <= n; len++) {
      long acc = 0;
      for (int d = b - 1; d >= 0; d--) {
        acc = (acc + ways[len - 1][d]) % MOD;
        ways[len][d] = acc;
      }
    }
    long res = 0;
    for (int len = 1; len < n; len++) res += ways[len][1];
    int prev = 1;
    boolean full = true;
    for (int i = 0; i < n; i++) {
      int digit = s.charAt(i) - '0';
      for (int d = i == 0 ? 1 : prev; d < digit; d++) res += ways[n - i - 1][d];
      if (digit < prev) {
        full = false;
        break;
      }
      prev = digit;
    }
    if (full) res++;
    return res % MOD;
  }

  public int countNumbers(String l, String r, int b) {
    java.math.BigInteger lo = new java.math.BigInteger(l), hi = new java.math.BigInteger(r);
    String ls = lo.toString(b);
    boolean nd = true;
    for (int i = 1; i < ls.length(); i++) if (ls.charAt(i) < ls.charAt(i - 1)) nd = false;
    long ans = countUpTo(hi, b) - countUpTo(lo, b) + (nd ? 1 : 0);
    return (int) (((ans % MOD) + MOD) % MOD);
  }
}
